function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sb15d($m,$ep,$p=null){
  $ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));
  curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>25]);
  if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));
  $b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];
}
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $action=$_POST['action']??'';
  if($action==='add'){
    sb15d('POST','creative_intelligence_assets',[[
      'asset_type'=>$_POST['asset_type']??'idea','brand_pillar'=>$_POST['brand_pillar']??'mark_pires','title'=>$_POST['title']??'',
      'hook'=>$_POST['hook']??'','description'=>$_POST['description']??'','source_url'=>$_POST['source_url']??'','town'=>$_POST['town']??'',
      'audience'=>$_POST['audience']??'seller','production_effort_score'=>(int)($_POST['production_effort_score']??40),
      'status'=>'active','created_at'=>date('c'),'updated_at'=>date('c')
    ]]); $msg='Creative asset added.';
  } else {
    $id=$_POST['id']??''; $rec=$_POST['recommendation']??'';
    if($id && in_array($rec,['publish','create','rewrite','expand','repurpose','archive','review'],true)){
      sb15d('PATCH','creative_intelligence_assets?id=eq.'.rawurlencode($id),['recommendation'=>$rec,'approved_for_distribution'=>$rec==='publish'||$rec==='repurpose','updated_at'=>date('c')]);
      $msg='Creative recommendation updated.';
    }
  }
}
$rows=sb15d('GET','creative_intelligence_assets?select=*&status=eq.active&order=creative_impact_score.desc,created_at.desc&limit=400');
