foreach($rows as $r){$rec=$r['recommendation']??''; if(isset($stats[$rec]))$stats[$rec]++; if(($r['brand_pillar']??'')==='discover_ct')$stats['discover']++; if(($r['brand_pillar']??'')==='house_detective')$stats['detective']++; if(($r['audience']??'')==='seller')$stats['seller']++;}
